import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"UGSo Spezial","description":"Lignes SVG animées et nœuds de sommation pour ioBroker VIS 2.","frontmatter":{"title":"UGSo Spezial","description":"Lignes SVG animées et nœuds de sommation pour ioBroker VIS 2."},"headers":[],"relativePath":"fr/iobroker/widgets/ugso-spezial/index.md","filePath":"fr/iobroker/widgets/ugso-spezial/index.md","lastUpdated":1793807739000}'),r={name:"fr/iobroker/widgets/ugso-spezial/index.md"};function n(o,e,l,u,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="ugso-spezial" tabindex="-1">UGSo Spezial <a class="header-anchor" href="#ugso-spezial" aria-label="Permalink to &quot;UGSo Spezial&quot;">​</a></h1><p><strong>UGSo Spezial</strong> permet de visualiser des flux de données dans VIS 2, par exemple la puissance de plusieurs appareils. Le pack contient deux widgets.</p><h2 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h2><ul><li><strong>SVG-Line</strong> relie des points par un tracé droit, à angle droit ou passant par des points intermédiaires. Les couleurs, les longueurs des tirets et les pointes de flèche sont réglables. Une valeur positive anime la ligne vers l’avant, une valeur négative inverse le sens et une valeur nulle arrête l’animation. La vitesse peut être fixe ou proportionnelle à la valeur absolue.</li><li><strong>SVG LineBox</strong> additionne jusqu’à quatre entrées et une valeur de correction facultative. Le total peut être transmis à deux lignes de sortie au maximum ou écrit, dans la vue d’exécution, dans un état numérique existant et modifiable sous <code>0_userdata.0</code>. Si une entrée sélectionnée est indisponible, le nœud attend sa valeur.</li></ul><p>Dans l’éditeur, faites glisser une extrémité jaune pour l’aimanter à une autre ligne ou à une LineBox. Une extrémité munie d’une flèche ne peut pas s’aimanter. L’aimantation aligne le dessin ; le transfert des valeurs se configure séparément dans la LineBox.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>Une installation VIS 2 opérationnelle est nécessaire. Installez le pack via son URL GitHub dans ioBroker Admin (mode expert). Après une mise à jour, redémarrez VIS 2 pour charger la nouvelle version. Les deux widgets figurent dans la palette de l’éditeur sous <strong>UGSo Spezial</strong>.</p><ul><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-spezial" target="_blank" rel="noreferrer">GitHub</a></li><li><a href="https://github.com/rockbaer2007/ioBroker.vis-2-widgets-ugso-spezial/releases" target="_blank" rel="noreferrer">Releases</a></li><li><a href="https://www.npmjs.com/package/iobroker.vis-2-widgets-ugso-spezial" target="_blank" rel="noreferrer">npm</a></li></ul>',8)])])}const m=a(r,[["render",n]]);export{c as __pageData,m as default};
